/// <summary>
/// Updates multiple <c>WMSOrderTrans</c> records.
/// </summary>
/// <param name="_packedMap">
/// A packed map.
/// </param>
/// <param name="_wmsPickPalletId">
/// A <c>WMSPickPalletID</c> value; optional.
/// </param>
/// <param name="_worker">
/// The worker that performs the operation; optional.
/// </param>
/// <param name="_time">
/// The duration of the operation; optional.
/// </param>
/// <remarks>
/// An <c>OrderId</c> value is required for performance reasons so an index can be used.
/// </remarks>
/// <exception cref="M:exception::UpdateConflict">
/// An update conflict occurred.
/// </exception>
/// <exception cref="M:exception::UpdateConflictNotRecovered">
/// An update conflict cannot be recovered.
/// </exception>
/// <exception cref="M:exception::error">
/// The <c>RecVersion</c> passed as argument differs from the <c>RecVersion</c> of the selected record
/// </exception>
static public void finishPickingLinesMulti(
    container           _packedMap,
    WMSPickPalletId     _wmsPickPalletId,
    HcmWorkerRecId      _worker,
    WMSExpeditionTime   _time)
{
    next finishPickingLinesMulti(_packedMap, _wmsPickPalletId, _worker, _time);

    WMSOrderTransType::setOrdersForRepricing(_packedMap);
    WMSOrderTransType::METCustomerMDFCalculation(_packedMap);
}

/// <summary>
/// set eligible orders for repricing after picking
/// </summary>
/// <param name = "_metPackedList">packedList</param>
public static void setOrdersForRepricing(container   _metPackedMap)
{
    WMSOrderTrans   wmsOrderTrans;
    SalesTable          salesTable;
    CustTable           custTable;
    METCustTable        metCustTable;
    SalesLine           salesLine;
    METIndustryKeyTable metIndustryKeyTable;
    METSalesInvoiceIndicatorView    metSalesInvoiceIndicatorView;


    Set                 ordersForRepricingSet = new Set(Types::String);

    if (!_metPackedMap)
    {
        return;
    }

    Map selectedWMSOrderTrans = Map::create(_metPackedMap);

    if (!selectedWMSOrderTrans)
    {
        return;
    }

    MapEnumerator metListEnumerator = selectedWMSOrderTrans.getEnumerator();

    while (metListEnumerator.moveNext())
    {
        RecId wMSOrderTransRecId = metListEnumerator.currentKey();

        select firstonly wmsOrderTrans
            where wmsOrderTrans.RecId == wMSOrderTransRecId;

        if (wmsOrderTrans.inventTransType == InventTransType::Sales && !ordersForRepricingSet.in(wmsOrderTrans.inventTransRefId))
        {
            select firstonly salesTable
                where salesTable.SalesId == wmsOrderTrans.inventTransRefId
                exists join metCustTable
                    where metCustTable.AccountNum == salesTable.CustAccount
                exists join metIndustryKeyTable
                    where metIndustryKeyTable.IndustryKey == metCustTable.IndustryKey;

            if (metIndustryKeyTable.RepriceAfterPicking)
            {
                while select forupdate salesLine
                    order by salesLine.LineNum asc
                    where salesLine.SalesId     == salesTable.SalesId
                        join metSalesInvoiceIndicatorView
                            where metSalesInvoiceIndicatorView.InventTransId   == salesLine.InventTransId
                {
                    if (metSalesInvoiceIndicatorView.CimponentInvoiceIndicator == METInvoiceIndicator::B)
                    {
                        SalesUpdateRemain::updateDeliveryRemainder(salesLine, 0, 0);
                    }
                    else
                    {
                        salesLine.metDeletePriceComponents();
                    }
                }

                ttsbegin;
                METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);
                if (metSalesTable)
                {
                    metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::RepriceRequired;
                    metSalesTable.update();
                }
                ordersForRepricingSet.add(salesTable.SalesId);
                ttscommit;
            }
        }
    }
}

/// <summary>
/// Calculate Customer MDF for all WMSPickingRouteId in the packed list
/// </summary>
/// <param name = "_metPackedList">container</param>
public static void METCustomerMDFCalculation(container _packedMap)
{
    METCustomerMDFCalculation_WMSOrderTrans custMDFCalculation = new METCustomerMDFCalculation_WMSOrderTrans();
    custMDFCalculation.parmWMSOrderTransMulti(_packedMap);
    custMDFCalculation.process();
}
